detailed_slides_ch6_to_10 = [{'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 1, 'title': '告別逐行回車確認：Auto Mode 的誕生背景', 'subtitle': '當計畫足夠堅固，逐次按『y』批准已成為最大的時間小偷', 'takeaway': 'Auto Mode 允許工程師在審批完 plan.md 後，授權 Claude Code 自主套用多步改動，無須每處編輯按次回車。', 'details': ['<strong>手動確認的心理摩擦</strong>：看著終端一處處彈出『Do you want to edit foo.ts? (y/n)』，工程師被迫像人肉打樁機一樣機械式敲回車。', '<strong>從『微觀監工』邁向『宏觀驗收』</strong>：當邊界清晰且有測試保護時，逐行確認並不能增加安全性，反而嚴重破壞思考心流。', '<strong>自動應答的底氣所在</strong>：Auto Mode 不是盲目冒險，它的前提是 Stage 2 的緊湊 spec 與 Stage 3 的周密 plan.md。'], 'metaphor': '就像在工廠裡，你已經向技術熟練的工匠交代了精準的裝配圖紙，你不需要站在他身後，每當他拿起一把螺絲刀都得向你敬禮請示：『報告長官，我現在可以擰這顆螺絲了嗎？』', 'layout': '心理耗損對比圖：左側展示被 50 次 (y/n) 打斷的破碎心流，右側展示 Auto Mode 一氣呵成的順暢生產力曲線。'}, {'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 2, 'title': 'Auto-accept 成為默認狀態的成熟度條件', 'subtitle': '四重防護網就緒後的安全放權', 'takeaway': '唯有當 CLAUDE.md、Skills、Hooks 與本機測試四大護欄成熟時，Auto-accept 才能安全成為日常默認。', 'details': ['<strong>條件一：微調好的 CLAUDE.md</strong>：為 Agent 提供清晰的架構約束與避坑指南，避免低級錯誤。', '<strong>條件二：制度化的 Skills</strong>：自動套用組織級的編碼標準與安全規範。', '<strong>條件三：確定性的 Hooks 攔截</strong>：在本地物理阻斷對保護路徑的意外竄改。', '<strong>條件四：完備的自動化測試套件</strong>：Agent 寫完代碼能夠立即自主運行測試驗證綠燈。'], 'metaphor': '這就像汽車的『主動防撞與車道偏離輔助系統』：唯有當雷達、攝影鏡頭、ABS 煞車與行車電腦全部通過自檢時，儀表板上的全自動定速巡航燈號才會亮起綠燈。', 'layout': '四重護城河雷達圖：展示 CLAUDE.md、Skills、Hooks、Tests 四大支柱如何共同支撐起 Auto Mode 的安全基座。'}, {'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 3, 'title': '小爆炸半徑原則 (Small Blast Radius)', 'subtitle': '什麼樣的任務適合全自動？劃定放權邊界', 'takeaway': '緊湊的 spec、狹小的破壞半徑、且代碼已被現有測試充分覆蓋的任務，是 Auto Mode 的最佳戰場。', 'details': ['<strong>高契合度任務特徵</strong>：修復邊界 Bug、新增純展示型 UI 元件、為現有 API 新增過濾欄位、更新文檔與單元測試。', '<strong>低契合度高危任務</strong>：核心資料庫遷移、跨十個微服務的底層協定變更、涉及千萬級用戶權限體系重構。', '<strong>階梯式授權策略</strong>：依據爆炸半徑動態調整監督等級，常規工作全速奔馳，高危工作收緊至半自動步進。'], 'metaphor': '就像在化學實驗室裡：混合兩瓶溫和的食鹽水（小半徑任務），你可以放心交給自動攪拌機運轉；但如果涉及硝酸甘油調配（高危任務），教授必須親自穿上防爆服近距離操作。', 'layout': '2x2 決策象限圖：橫軸為爆炸半徑大小，縱軸為測試覆蓋率，右上角標註『Auto Mode 甜點區』。'}, {'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 4, 'title': '人機互動重心的歷史性轉移：事後產物審查', 'subtitle': '從盯著終端螢幕看字符跳動，轉向審視長時間自主工作後的完整 Artifact', 'takeaway': '工程師的角色從『在線即時監工』徹底升級為『離線交付審查官』，釋放寶貴的即時等待時間。', 'details': ['<strong>擺脫終端機凝視</strong>：過去工程師不敢離開螢幕，生怕 Agent 走火入魔；在 Auto Mode 下，你可以放心泡一杯咖啡或切換處理另一項任務。', '<strong>長時間自主對話 (Long Autonomous Sessions)</strong>：Agent 在背景自主進行 20 分鐘的探索、代碼修改、除錯與測試運行。', '<strong>專注於最終產物的綜合驗收</strong>：回來時直接檢視 Git Diff、生成的測試報告與架構一致性證明，評估整體完成度。'], 'metaphor': '如同委託資深裝潢師傅粉刷房間，你不需要搬張椅子坐在油漆桶旁邊盯著他每一刷的動作，你只要在下班回來後檢查整面牆是否平整、顏色是否均勻、邊角是否有污漬。', 'layout': '時間分配轉移圖：將『盯梢等待時間 70%』成功替換為『非同步專注自身業務 + 10% 集中審閱』的高效模式。'}, {'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 5, 'title': '結合 Git Worktrees 實現個人產能的並行倍增', 'subtitle': '一人驅動三條獨立產線：告別多分支頻繁切換的痛苦', 'takeaway': 'Auto Mode 與 Git Worktrees 是天作之合，允許一個工程師在本地同時掛起多個相互隔離的 Agent 自主任務。', 'details': ['<strong>Worktrees 物理目錄隔離</strong>：每個獨立任務擁有自己專屬的實體檔案夾與 Git 分支，徹底解決單一倉庫切換分支編譯鎖定衝突。', '<strong>並行終端窗口驅動</strong>：終端 1 在 `worktree-auth` 開啟 Auto Mode 實作身分模組；終端 2 在 `worktree-cache` 開啟 Auto Mode 修復 Redis 限流。', '<strong>人成為調度樞紐</strong>：工程師在多個工作區之間巡檢，哪邊完成自主實作就驗收哪邊，個人生產力實現非線性幾何暴增。'], 'metaphor': '這就像五星級大廚同時管理四個灶台：一號灶慢燉高湯（Worktree A），二號灶烤箱低溫烘烤牛排（Worktree B），三號灶大火翻炒時蔬（Worktree C），大廚只需穿梭調味擺盤。', 'layout': '多終端並行拓撲圖：一個工程師大腦同時連接三個獨立的 Git Worktrees，下方標註無衝突的目錄結構。'}, {'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 6, 'title': 'Auto Mode 下的安全防禦防護網：無聲守護者', 'subtitle': '當放手讓 Agent 奔馳時，底層防線如何確保不脫軌？', 'takeaway': '在 Auto Mode 下，Hooks 的確定性防護地位更加凸顯，成為 Agent 無法逾越的物理安全底線。', 'details': ['<strong>PreToolUse 實時動態攔截</strong>：即使開啟了 Auto Mode，底層 Hook 依然對每一次 Tool 調用進行微秒級過濾，越權動作即刻彈出紅牌。', '<strong>自適應中斷機制</strong>：如果連續多次測試失敗或進入邏輯死循環，系統自動退出 Auto Mode 並發送通知喚醒人類介入。', '<strong>變更透明可回溯</strong>：所有自動套用的變更在本地都有完整的 Stash 或 commit log，一鍵即可完全還原至乾淨初始態。'], 'metaphor': '宛如現代高鐵的 ATP (Automatic Train Protection) 自動列車防護系統：司機可以將列車設定為自動巡航，但一旦經過紅燈區間或超速，ATP 會瞬間強制介入制動停車。', 'layout': '安全防禦架構圖：Auto Mode 引擎高速運轉，外圍包裹著 PreToolUse Hooks 實時雷達掃描網與緊急制動閥。'}, {'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 7, 'title': 'Stage 6 閉環維運的基石：自主研發工廠的核心動力', 'subtitle': '沒有 Auto Mode，完全無人值守的自主修復閉環將無從談起', 'takeaway': 'Auto-accept 不僅造福個人工程師，更是 Stage 6 實現生產環境監控警報自動修復閉環的底層引擎。', 'details': ['<strong>無人值守閉環要求</strong>：當生產環境指標異常觸發自愈管線時，系統無法停下來等待工程師在深夜 3 點按回車批准。', '<strong>全自動端到端推動</strong>：Stage 6 的 Headless Worker 依賴 Auto Mode，在沙盒環境中自動讀取 intent、生成計畫、編寫代碼並提交 PR。', '<strong>門禁轉移至 PR 階段</strong>：所有的自主操作最終匯流至 Stage 5 的 PR 審查門禁，由隔天早晨的值班工程師集中驗收審批。'], 'metaphor': '就像全自動化工廠的夜間無人值守生產模式：夜間車間關燈後，機器人依然根據訂單排程自動切削裝配，只將最後的質檢合格品推送到出貨碼頭等待晨檢。', 'layout': '夜間閉環流水線示意圖：展示生產異常如何無人值守調用 Auto Mode 實作，並安全抵達審查門禁。'}, {'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 8, 'title': '實戰避坑指南：Auto Mode 的常見陷阱與對策', 'subtitle': 'Anthropic 實戰工程團隊踩過的坑與黃金教訓', 'takeaway': '防範過度依賴、盲目放權與代碼庫悄然膨脹，建立健康平衡的使用文化。', 'details': ['<strong>陷阱一：對模糊計畫開啟 Auto Mode</strong>：plan.md 還沒想清楚就放手讓它跑，結果產出大量方向偏離的無效垃圾代碼。', '<strong>陷阱二：測試覆蓋不足下的盲目自信</strong>：本地缺少自動化測試，Agent 自我感覺良好地改了 20 個檔案，實際上一跑全是 Runtime Error。', '<strong>黃金定則</strong>：嚴格遵循『先 Plan 明確、再 Auto 執行、後 Test 驗證』的三部曲，絕不在混沌狀態下啟動全自動。'], 'metaphor': '不要把一輛自動駕駛汽車開進沒有地圖資料、沒有道路標線且沒有行車感測器的原始森林裡去開啟最高車速巡航。', 'layout': '三組警示看板：展示『模糊計畫、零測試覆蓋、範圍過大』三大危險禁區及對應的安全處方。'}, {'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 9, 'title': '團隊級配置管理：透過受管設定統一行為', 'subtitle': '避免個別工程師隨意關閉防護，確保全組織安全基線', 'takeaway': '在企業環境中，Auto Mode 的放權權限應與組織受管設定 (Managed Settings) 連動，落實分級管控。', 'details': ['<strong>敏感分支禁用全自動直推</strong>：配置規則鎖定保護分支（如 main/prod），Auto Mode 產生的任何變更強制只能存在於 feature 分支中。', '<strong>設定集中式白名單</strong>：IT 管理員可設定哪些指令允許在 Auto 模式下執行，哪些高危指令（如 rm -rf、drop table）必須強制彈出確認。', '<strong>合規審計全量存證</strong>：Auto Mode 期間調用的所有工具動作與參數，全數在背後打上時間戳並流式寫入企業審計日誌。'], 'metaphor': '如同特種車輛限速器：雖然賽車手技術高超，但市政救護車在市區行駛依然受到車載黑盒子限速與 GPS 全程軌跡記錄的法定硬性約束。', 'layout': '中央受管設定控制台示意圖：展示組織策略如何向下推送到每位工程師的本地終端環境。'}, {'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 10, 'title': '工程師心理學變革：重塑產出成就感與控制感', 'subtitle': '從『逐行敲代碼的工匠心態』走向『掌控千軍萬馬的元帥心態』', 'takeaway': '克服『不親手敲每一行代碼就心慌』的心理障礙，體會架構設計與結果驗證帶來的更高層次成就感。', 'details': ['<strong>破除代碼虛榮心</strong>：敲代碼行數從來不等於商業價值，架構優雅性、系統穩定性與業務創新交付速度才是工程師的最高榮譽。', '<strong>建立高品質驗收眼光</strong>：學會如何從成百上千行的 Diff 中迅速敏銳地捕捉架構缺陷、極限邊界漏洞與潛在效能瓶頸。', '<strong>專注力的極致釋放</strong>：將省下來的寶貴精力，投入到新技術預研、業務架構深度溝通與底層演算法突破上。'], 'metaphor': '這就像從一位每天在沙灘上手工挑揀貝殼的潛水員，晉升為指揮一整支深海探測潛水艇艦隊的海洋科學考察首席科學家。', 'layout': '思維模型演進圖：從『細節工匠』躍遷至『系統架構師』的心理認知與價值天花板躍遷。'}, {'chapter_id': 6, 'chapter_name': '第 6 章：Stage 3: Build — Auto Mode 與自主執行', 'page_num': 11, 'title': '第六章實戰總結：安全釋放十倍工程效能', 'subtitle': 'Stage 3 Build 自主執行核心精髓與下章預告', 'takeaway': 'Auto Mode 讓工程師徹底擺脫機械重複勞動，配合 Worktrees 實現一人成軍；下章我們將深入守護這一切的知識基石——CLAUDE.md！', 'details': ['<strong>核心公式</strong>：嚴謹 plan.md + 健全護欄 + 小爆炸半徑 + Auto Mode = 極速高質交付。', '<strong>行動建議</strong>：今天就為你的日常開發分支嘗試開啟一次 Auto Mode，體驗非同步審查帶來的極致專注心流。', '<strong>前瞻下一章</strong>：Agent 每次啟動究竟該如何精準繼承團隊的所有潛規則與架構智慧？第七章將為您徹底揭密 CLAUDE.md 的架構心法！'], 'metaphor': '當發動機的齒輪已經嚴絲合縫，請勇敢踩下油門，在安全護欄的護航下，享受飛馳在軟體工程全新高速公路上的極致快感。', 'layout': '三條核心守則總結卡片，底部搭配通往第七章 CLAUDE.md 的高亮引導箭頭。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 1, 'title': '大腦的開機配置：為什麼每個倉庫都需要 CLAUDE.md？', 'subtitle': '將沉澱在大腦與 Wiki 中的潛規則，化為 Agent 每次啟動必讀的上下文', 'takeaway': 'CLAUDE.md 是新加入工程師第一天上班所需的一切核心上下文，覆蓋常用命令、架構慣例與高頻踩坑禁忌。', 'details': ['<strong>拯救散落的隱性知識</strong>：公司內部無數不言自明的約定（如『貨幣只能用 BigDecimal』）過去只存在資深員工口中，新人和 Agent 極易踩雷。', '<strong>開箱即用的冷啟動</strong>：Agent 進入陌生代碼庫的第一時間，透過根目錄的 CLAUDE.md 瞬間熟悉全局架構與日常規範，宛如資深員工附身。', '<strong>集中維護與代碼同壽</strong>：不再將架構手冊放任在發霉的 Confluence 頁面上，而是與代碼放置在同一 Git 倉庫中同步審查演進。'], 'metaphor': '這就像新員工入職第一天，師傅遞給他的一張塑膠護貝的『終極通關小抄』：上面寫著伺服器密碼重置規則、各模組負責人是誰、以及微波爐絕對不能加熱金屬便當盒等保命常識。', 'layout': '雙向轉換圖：左側展示雜亂無章的 Wiki、Slack 聊天記錄，透過中央過濾漏斗，右側凝聚成簡潔強悍的 CLAUDE.md。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 2, 'title': '執行 /init 自動生成：萃取專案技術基因', 'subtitle': '從零起步的最佳途徑：讓 Claude 深入掃描代碼庫結構', 'takeaway': '在專案根目錄鍵入 /init，Claude 將主動分析專案檔案、建置腳本與目錄結構，自動提煉出一份高質量的初版 CLAUDE.md。', 'details': ['<strong>自動探測建置與測試指令</strong>：掃描 package.json、Makefile、pom.xml 或 Cargo.toml，精準識別常用 build/test 指令。', '<strong>識別核心架構分層</strong>：辨識前後端目錄結構、資料庫遷移腳本存放路徑與 API 定義規範。', '<strong>人類工程師的精簡裁切</strong>：/init 生成的文件只是原材料，工程師必須大刀闊斧剪除冗餘，只保留第一天必須知曉的關鍵命脈。'], 'metaphor': '就像地質學家帶著探地雷達在未知島嶼上掃描一圈（/init），立刻標註出淡水源、金屬礦脈與斷層帶，繪製出第一張基礎拓荒軍用地圖。', 'layout': '終端互動示意圖：鍵入 /init 命令，展示 Claude 掃描各專案目錄並輸出結構化草案的動態過程。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 3, 'title': '四大核心板塊設計：Commands, Conventions, Architecture, Mistakes', 'subtitle': 'Anthropic 官方規範的黃金四段式架構', 'takeaway': '一份結構優秀的 CLAUDE.md 必須嚴格包含：常用命令、編碼慣例、系統架構概覽與高頻避坑清單。', 'details': ['<strong>Commands（建置與測試指令）</strong>：提供標準執行腳本，並清晰標註健康輸出範例，讓 Agent 能自主運行。', '<strong>Conventions（團隊約定）</strong>：語言版本標準、禁用的舊庫、特定資料型別強制規範（如禁 double、強制 BigDecimal）。', '<strong>Architecture（架構導航）</strong>：REST 控制器在 api/、領域邏輯在 core/、外部介面在 adapters/，模組邊界一清二楚。', '<strong>Things Claude gets wrong（高頻踩坑清單）</strong>：明確警示 Agent 過去最容易犯錯的盲區（如禁自作主張升級依賴）。'], 'metaphor': '這就像古代軍營的『治軍四訓』：一訓軍號口令（Commands）、二訓操練陣式（Architecture）、三訓軍規軍紀（Conventions）、四訓斬立決重罪（Things not to do）。', 'layout': '四宮格卡片版面：分別展示 Commands、Conventions、Architecture、Things Claude gets wrong 的標準排版。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 4, 'title': '官方實戰範例拆解：支付微服務的真實設定', 'subtitle': '僅僅一頁紙，如何精準約束一個複雜的 Spring Boot 專案？', 'takeaway': 'Anthropic 原文範例向我們展示了極致精簡與高度權威性的完美結合。', 'details': ['```markdown\n# Payments service\n\n## Commands\n- Build: make build\n- Test: make test (unit), make itest (integration, needs docker)\n- Lint: make lint (runs in CI; fix before pushing)\n\n## Conventions\n- Java 21, Spring Boot 3. No new Lombok.\n- Money is always BigDecimal, never double.\n- Every endpoint needs an integration test in src/itest.\n\n## Architecture\n- api/ holds REST controllers, core/ holds domain logic,\n  adapters/ talks to external systems.\n- Kafka events are defined in schemas/; never edit generated classes.\n\n## Things Claude gets wrong\n- Do not bump dependency versions; the platform team owns them.\n- The legacy v1/ package is frozen; changes go in v2/.\n```', '<strong>金錢精度鐵律</strong>：『Money is always BigDecimal, never double』徹底消滅浮點數舍入財務事故。', '<strong>凍結舊包保護</strong>：『The legacy v1/ package is frozen』直接在第一時間斷絕了 Agent 篡改舊遺留系統的可能。'], 'metaphor': '宛如十誡石碑：文字極其精練，沒有一句廢話，但每一條誡命都精準命中了歷史上無數血淋淋的慘痛教訓。', 'layout': '代碼高亮展示官方 Payments service CLAUDE.md 全文，重點行次以亮藍色標註解說。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 5, 'title': '犯錯兩次法則 (The Mistake Rule)：動態演進的智慧庫', 'subtitle': '不要指責 Agent，要將錯誤化為不可磨滅的制度防禦', 'takeaway': '當 Claude 在開發或審查中第二次犯下同樣的錯誤時，修正必須立即作為一條新規則寫入 CLAUDE.md。', 'details': ['<strong>從抱怨 AI 轉向制度修復</strong>：遇到 Agent 寫錯代碼，僅僅在聊天視窗斥責毫無意義；關閉視窗後，下個對話依然會重蹈覆轍。', '<strong>一處受傷，全員免疫</strong>：工程師在 PR 審查時把教訓寫入根目錄的 CLAUDE.md，自此全公司所有的工程師與 Agent 在下次啟動時瞬間獲得免疫力。', '<strong>動態生長的知識有機體</strong>：代碼庫經歷一年的實戰打磨，CLAUDE.md 將沉澱為該領域最權威、最珍貴的專屬工程百科全書。'], 'metaphor': '這就像現代航空安全事故調查機制：每次黑盒子破譯出事故原因後，波音與空巴立刻將修正後的標準檢查程序 (Checklist) 發送到全球所有飛行員的駕駛手冊中，終身杜絕同類空難再度發生。', 'layout': '閉環演進迴圈圖：Agent 犯錯 → 人類指出修正 → 寫入 CLAUDE.md → 全域對話即刻免疫的進化閉環。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 6, 'title': '上下文長度控制：為什麼必須嚴格控制在一頁紙以內？', 'subtitle': '少即是多：避免注意力稀釋 (Context Dilution) 與 Token 浪費', 'takeaway': '因為 Claude 在每次開啟新會話時都會全量閱讀 CLAUDE.md，過時、冗長或過細的內容只會擠佔寶貴的思考窗口。', 'details': ['<strong>上下文稀釋效應</strong>：當文件超過千行，大語言模型對個別關鍵誡命的注意力權重將不可避免地下滑，反而容易遺忘核心約束。', '<strong>過時資訊是隱形毒藥</strong>：三個月前寫死在裡面的臨時依賴版本，很可能在系統升級後誤導 Agent 做出荒謬的逆向降級。', '<strong>嚴格劃定邊界</strong>：只保留全域性的黃金規則；凡是針對特定領域的深度規範（如複雜的 API 安全審查條例），應移出並封裝為獨立的 Skill！'], 'metaphor': '如同特種部隊突擊隊員的隨身戰術腰帶：只能放置求生刀、急救止血帶與彈匣；如果你把整部大英百科全書綁在腰帶上，隊員只會被壓得寸步難行、喪失戰鬥力。', 'layout': '長度對比標尺圖：展示一頁紙 (30~50行) 的黃金甜點區，以及過度膨脹導致模型注意力衰減的警告紅區。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 7, 'title': '驗證段落規範：將 Verification 內化為完成標準', 'subtitle': '明確定義何謂『Done』：不跑綠燈測試禁止回報完成', 'takeaway': '在 CLAUDE.md 中明確寫入 Verifying your work 區塊，命令 Agent 必須在回報任務完成前自主運行所有測試並貼出輸出。', 'details': ['<strong>拒絕假象完成</strong>：杜絕 Agent 寫完代碼後隨口回報『我已經幫你實現好了』，實則編譯根本跑不通的尷尬境地。', '<strong>明確退出指標</strong>：包含 Build、Test、Lint 三大強制檢驗項，要求 Lint 必須零警告，測試全綠且絕不允許跳過或刪除失敗測試。', '<strong>修復代碼而非修復測試</strong>：白紙黑字規定『If a test fails, fix the code, not the test』，從根本上斬斷 Agent 為了投機取巧偷改測試斷言的劣習。'], 'metaphor': '就像外科手術室的『手術器械計數清單』：護士長必須在主刀醫生縫合傷口前，逐件清點紗布與止血鉗數量完全吻合並大聲報讀，才能宣告手術結束。', 'layout': '代碼區塊展示標準 Verifying your work 配置，右側標註『強制輸出證明、禁止竄改測試』雙重圖章。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 8, 'title': '版本控制與 Code Review：像對待代碼一樣對待指令', 'subtitle': 'CLAUDE.md 享有與核心業務邏輯完全相同的代碼地位', 'takeaway': 'CLAUDE.md 必須被納入 Git 根目錄，全團隊共享一份真相，任何修改都必須經過 Pull Request 與 Code Owner 嚴格審批。', 'details': ['<strong>嚴禁本地私藏</strong>：禁止工程師將關鍵配置只放在本地環境，全團隊必須步調一致，共享同一個 Agent 大腦設定。', '<strong>審計透明化</strong>：每次規則修訂都有具名的 Git 提交記錄，誰在何時、因何事故調整了架構約束，歷歷在目。', '<strong>Code Owner 強制把關</strong>：只有資深架構師或平台工程師擁有批准 CLAUDE.md 變更的權限，防止不成熟的個人偏好污染全局環境。'], 'metaphor': '這就像國家的『憲法修正案』：憲法條文公開印製發行給所有公民，任何人不能在私底下偷改法條，任何條文修訂都必須經過國會全體辯論與三分之二多數表決通過。', 'layout': 'PR 流程圖：展示修改 CLAUDE.md 建立分支 → CI Evals 自動跑回歸 → 架構師 Code Review 簽署 → 合併生效的全流程。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 9, 'title': 'PR Review 反饋機制：讓審查持續滋養知識庫', 'subtitle': '當 PR Review 發現二次失誤時，自動發起 CLAUDE.md 更新', 'takeaway': '在 Stage 5 的 PR Review 中，一旦審查機器人或人工評審第二次抓出同類命名或邏輯偏誤，直接在該 PR 中提議更新 CLAUDE.md。', 'details': ['<strong>審查與知識庫的雙向互哺</strong>：PR Review 既是代碼的把關者，也是 CLAUDE.md 規則是否有效的即時檢驗場。', '<strong>及時識別過時規則</strong>：當專案完成 Spring Boot 3 升級後，Review 流程會主動警示『CLAUDE.md 中舊版的 Java 17 規範已過期，請同步修正』。', '<strong>全自動健康巡檢</strong>：每月定期評估 CLAUDE.md 中每條規則的命中率與攔截效果，淘汰無效噪音，保持精幹強健。'], 'metaphor': '就像在現代軍事演習中，前線假想敵部隊（PR Review）一旦發現防禦陣地存在重複的防禦盲區，立刻將該漏洞情報反饋給軍校教研室，當晚改寫作戰訓練教材。', 'layout': '雙向箭頭閉環：PR Review 發現重複問題 ⇆ 自動建議更新 CLAUDE.md ⇆ 下次對話 Agent 預防犯錯。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 10, 'title': '多專案組織分層治理：全局配置與模組覆蓋', 'subtitle': '在大型 Mono-repo 或多微服務巨型企業架構中的落地策略', 'takeaway': '採用『根目錄全局共享 + 子目錄按需覆蓋』的層次結構，兼顧全組織統一標準與子服務專屬特質。', 'details': ['<strong>全局基線 (Root CLAUDE.md)</strong>：定義全公司統一的 Git Commit 規範、安全底線與通訊協議。', '<strong>子模組特化 (Sub-module CLAUDE.md)</strong>：在 `frontend/` 或 `payment-service/` 等子目錄下放置專屬說明，覆蓋特定框架指令與測試命令。', '<strong>動態繼承與優先權判定</strong>：Claude Code 在進入特定目錄時，優先就近讀取子配置，並無縫繼承父級安全原則，兼顧靈活性與嚴肅性。'], 'metaphor': '如同聯邦法律與州法律的關係：聯邦憲法（Root CLAUDE.md）確立了不可侵犯的公民基本權利與國家安全底線；各州政府（子模組）可根據本地農業或商業特點頒布更具體的交通法規。', 'layout': '樹狀目錄分層架構圖：展示 Root CLAUDE.md 與各 Sub-package CLAUDE.md 之間的繼承與覆蓋關係。'}, {'chapter_id': 7, 'chapter_name': '第 7 章：Stage 3: Build — 團隊智慧庫：CLAUDE.md', 'page_num': 11, 'title': '第七章實戰總結：讓每一次犯錯都成為永恆的資產', 'subtitle': 'Stage 3 Build 團隊智慧核心心法與下章預告', 'takeaway': 'CLAUDE.md 是人機協同的大腦中樞，但若要承載深度、專業化的企業制度，我們需要更模組化的利器——Skills！', 'details': ['<strong>三大黃金法則</strong>：保持在 1 頁以內、恪守犯錯兩次法則、將完成標準 (Verification) 白紙黑字固化。', '<strong>立即行動</strong>：在終端機對你的核心倉庫運行一次 `/init`，提煉出屬於你們團隊的第一份 CLAUDE.md！', '<strong>前瞻第八章</strong>：當某些安全與 API 規範過於龐大、無法塞進一頁紙時該怎麼辦？第八章將為您呈現『Skills 機構知識模組化』的卓越架構！'], 'metaphor': '不貳過，是古代賢人的最高修養；而 CLAUDE.md 則是將這種最高修養，以一行行代碼與規範的形式，賦予了整個團隊的每一次 AI 工作階段。', 'layout': '三條核心實踐卡片，底部搭配通往第八章 Skills 的高亮躍遷箭頭。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 1, 'title': '什麼是 Agent Skills？將機構知識轉化為可執行操作', 'subtitle': '超越提示詞的模組化外掛：讓特定領域的專業規章成為活生生的能力', 'takeaway': 'Skills 是組織將制度化隱性知識轉化為標準化、版本控制、可廣泛分發且按需加載的模組化能力。', 'details': ['<strong>解決知識膨脹與混亂</strong>：如果把所有 API 規範、資安準則全部塞進 CLAUDE.md，檔案將迅速突破數萬字導致模型癱瘓；Skills 完美實現了按需解耦。', '<strong>明確的觸發邊界</strong>：每個 Skill 都有前置的 YAML 元數據宣告『何時應該被觸發』，Agent 只有在處理相關任務時才會精準加載。', '<strong>中央集中更新與即時生效</strong>：安全團隊更新了 API 安全標準，全公司所有工程師在下次啟動相關任務時，全自動繼承最新版防禦策略。'], 'metaphor': '就像急診室醫生隨身攜帶的『專業急救操作指南插卡』：平時不佔用大腦記憶體，但一遇到『心跳驟停』或『劇毒蛇咬傷』，醫生立刻抽取出對應卡片精準施救。', 'layout': '插卡式模組拓撲圖：Agent 主機作為底座，上方插滿了 API Security、Brand Guideline、DB Migration 等各類專業 Skill 插卡。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 2, 'title': 'Skills vs CLAUDE.md vs Prompts：黃金劃分界線', 'subtitle': 'Anthropic 官方經驗法則 (Rule of Thumb)：什麼內容該放在哪裡？', 'takeaway': '凡是全域必須知曉的一頁內放 CLAUDE.md；凡是單次自定義想法放 Prompt；凡是跨團隊必須一致執行的機構制度放 Skill！', 'details': ['<strong>CLAUDE.md 的職責</strong>：全倉庫開機必讀、建置測試指令、核心架構邊界、全域避坑禁忌（少於 1 頁）。', '<strong>Prompts 的職責</strong>：特定具體任務的臨時要求（如：『幫我把這個圖標換成綠色』），一次性消費即丟。', '<strong>Skills 的職責</strong>：在組織內執行參差不齊的制度化知識（如 API 安全標準、微服務通訊契約、合規審計埋點），需要被反覆嚴格落實。'], 'metaphor': 'CLAUDE.md 就像公司的『員工守則手冊』；Prompt 就像主管今天交辦的一張『即時便利貼』；而 Skill 則是厚重且權威的『特種設備操作執照認證手冊』。', 'layout': '三欄矩陣對照表：清晰比較 CLAUDE.md、Prompts 與 Skills 在觸發頻率、生命週期、擁有者與適用場景的本質差異。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 3, 'title': 'SKILL.md 檔案剖析：YAML Frontmatter 與指令主體', 'subtitle': '標準化目錄結構與語法規範：以 .claude/skills/<name>/SKILL.md 為家', 'takeaway': '一個標準的 Skill 包含兩個關鍵部分：描述觸發條件的 YAML 前置元數據，以及描述具體行動步驟的 Markdown 正文。', 'details': ['<strong>標準路徑約定</strong>：存放在倉庫根目錄的 `.claude/skills/<skill-name>/SKILL.md`，隨著代碼一起納入 Git 版本控制。', '<strong>YAML Frontmatter</strong>：定義 `name` 與 `description`。描述必須極其精確地說明『何時觸發（Trigger condition）』，引導 Agent 自動判斷調用時機。', '<strong>Markdown 內容主體</strong>：分步驟列出合規清單、參數格式、範例代碼與驗證腳本路徑，讓 Agent 照方抓藥。'], 'metaphor': '就像藥品包裝盒：正面標註適應症與用藥時機（YAML 元數據：咳嗽發燒時使用），盒子裡面附帶詳細的藥物化學結構與按體重計算的服用劑量說明書（Markdown 正文）。', 'layout': '雙層結構卡片展示：上半部為藍色背景的 YAML 元數據，下半部為白色背景的具體實施細則。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 4, 'title': '官方實戰範例拆解：secure-api-review 安全審查', 'subtitle': 'Anthropic 原文剖析：對外 API 端點的四大必殺防線', 'takeaway': '這個官方範例展示了如何用清晰、條理化的規則，在編碼當下徹底杜絕匿名訪問與 PII 外洩。', 'details': ['```markdown\n---\nname: secure-api-review\ndescription: Apply the API security standard. Use whenever creating or\n  modifying an external-facing endpoint, reviewing API code, or\n  generating an OpenAPI spec.\n---\n# Secure API review\n\nWhen you create or change an API endpoint:\n1. Authentication: every endpoint requires the gateway JWT;\n   no anonymous routes outside /health.\n2. Input validation: validate request bodies against the OpenAPI\n   schema and reject unknown fields.\n3. Audit: every state-changing endpoint emits an audit event with\n   actor, action, entity and timestamp.\n4. Data classification: fields tagged pii in the schema must never\n   appear in logs or error messages.\n\nRun scripts/check-endpoints.sh and include its output in your summary.\n```', '<strong>強制四項鐵律</strong>：JWT 驗證、嚴格輸入白名單過濾、狀態變更審計事件發射、PII 欄位日誌絕對脫敏。'], 'metaphor': '宛如民航客機起飛前的『防空識別與地空通信檢查單』：飛行員逐項勾選應答機編碼、高度表氣壓設定與二次雷達校準，漏勾一項禁止推入跑道。', 'layout': '代碼區塊完整高亮 secure-api-review 全文，四項條例配有醒目的安全盾牌圖示。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 5, 'title': '落地執行四步法：如何將一項團隊規範提煉為 Skill？', 'subtitle': '從發掘痛點到組織分發的完整工業化落地閉環', 'takeaway': '執行步驟：挑選一項執行不一致的痛點、協同負責人編寫 SKILL.md、測試觸發靈敏度、透過 Plugin 全局分發。', 'details': ['<strong>步驟一：鎖定一項痛點</strong>：挑選當前團隊中經常被違反的規範（如 API 設計風格、日誌脫敏、品牌前端元件）。', '<strong>步驟二：編寫 SKILL.md</strong>：工程師利用 Claude 協助，將資深政策主管的 Word/Wiki 文件轉化為精確的 Markdown 步驟與 YAML 觸發詞。', '<strong>步驟三：測試觸發邊界</strong>：用多種不同的用戶提示詞測試，確保 Agent 在該觸發時 100% 喚醒，不相關任務時絕不誤加載。', '<strong>步驟四：政策變更與簽核</strong>：政策更新時修改 Skill 並由政策主管審批，全團隊在下次對話中自動無縫繼承新標準。'], 'metaphor': '就像工業流水線製造模具：先找出手工打磨容易出次品的零件，將標準圖紙雕刻成高強度鋼製模具，試模衝壓確認無瑕疵後，分發給各車間直接衝壓生產。', 'layout': '四步流程進度條：痛點診斷 → 編寫封裝 → 靈敏度測試 → 組織分發發布。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 6, 'title': 'Skills 作為軟約束 (Advisory Control) 的本質局限', 'subtitle': '清醒認知：Skill 能極大降低犯錯機率，但不能保證 100% 零違規', 'takeaway': 'Skill 屬於諮詢式引導，是基於提示詞層面的『軟約束』；沒有任何物理力量能強制一個對話絕對不會偏離。', 'details': ['<strong>提示詞遵循度的客觀邊界</strong>：即使加載了 Skill，大語言模型在極端複雜或上下文衝擊下，依然存在微小概率遺漏某些條例。', '<strong>非確定性本質</strong>：Skill 讓 Agent 傾向於主動遵守規範，在代碼被敲下的當下盡量做對，大幅減少後續審查摩擦。', '<strong>硬約束兜底的絕對必要性</strong>：對於必須零容忍、絕不允許有任何例外的底線政策，後端必須配備確定性腳本（Hooks）作為防線！'], 'metaphor': 'Skill 就像是交通警察發放的『安全駕駛宣傳手冊』與路口豎立的『請減速慢行』告示牌：絕大多數司機會自覺遵章守紀，但要防止酒駕衝撞，路口依然必須安裝防撞石墩與阻車釘。', 'layout': '軟硬約束對比圖：左側展示 Skill 的智力引導與柔性防禦，右側展示確定性防禦的必要性與邊界。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 7, 'title': '軟硬兼施的組合拳架構：Skill 鋪路，Hook 把關', 'subtitle': 'Anthropic 官方推薦的最佳防禦陣型', 'takeaway': 'Skill 負責讓違規行為變得極其罕見 (Rare)，而 Hook 則負責讓違規行為變得完全不可能 (Impossible)！', 'details': ['<strong>前置智力賦能</strong>：Skill 引導 Agent 理解代碼為什麼要這樣寫、給出合規代碼骨架與最佳實務，避免盲人摸象。', '<strong>後置確定性截殺</strong>：Hook 在底層監控工具調用，一旦 Agent 偏離規範碰觸受保護路徑或遺漏 JWT，毫秒級截斷執行。', '<strong>絕佳的研發體驗</strong>：如果只有 Hook 沒有 Skill，Agent 將像個瞎子一樣不斷撞牆被拒；有了 Skill 引導，Agent 幾乎一次就能走通綠燈路徑。'], 'metaphor': '這就像一場高等級高爾夫球賽：Skill 是經驗豐富的球童，在耳邊輕聲指點風向、草紋與推桿力道（智力引導）；而球洞周圍的平整果嶺與邊界圍繩（Hook）則保證球絕不會滾落懸崖。', 'layout': '雙層防禦時序圖：Skill 提示在思考期生效 → Agent 生成合規代碼 → Tool 執行期由 Hook 進行確定性驗收放行。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 8, 'title': '企業級分發管道：透過組織 Plugins 統一管理', 'subtitle': '告別手動複製貼上，實現全公司幾千個代碼庫的秒級策略同步', 'takeaway': '利用 Antigravity / Claude Code 的 Plugin 機制，中心平台團隊可將通用 Skills 統一套件化，一鍵下發給全體團隊。', 'details': ['<strong>單一真相源</strong>：所有公共 Skills（如資安規範、日誌庫標準）存放在中心治理倉庫中，由各領域專家集中維護與發行版本。', '<strong>自動化依賴訂閱</strong>：各業務專案透過配置文件引入插件，每次 Agent 啟動時自動拉取最新通過測試的穩定 Skill 版本。', '<strong>避免標準碎片化</strong>：徹底杜絕『A 團隊還在用三年前的舊 API 規範，B 團隊用自己的土方法』的混亂局面。'], 'metaphor': '就像手機應用商店的自動靜默更新機制：當國家頒布了新的隱私條例，銀行 App 團隊在後台發布安全更新套件，全球用戶的手機在夜間充電時自動更新完畢，無需用戶手動重新下載安裝。', 'layout': '分發拓撲圖：中央 Plugin Registry 向幾十個微服務代碼庫輻射推送最新 Skills 套件。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 9, 'title': '驗證與測試 Skill：確保觸發的精準度', 'subtitle': '如何避免 Skill 成為僵死無效的沉睡文件？', 'takeaway': '必須為 Skill 建立專屬的觸發測試用例，用多種不同提問方式確認 Agent 確實能被激活動態加載。', 'details': ['<strong>測試正面觸發 (Positive Test)</strong>：嘗試多種表達方式（如『幫我開一個給外部調用的用戶查詢接口』），驗證 `secure-api-review` 確實每次都能被自動載入。', '<strong>測試負面排除 (Negative Test)</strong>：提出不相干問題（如『幫我寫一個字串反轉工具函式』），驗證該 Skill 不會被無謂加載污染上下文。', '<strong>評估建議落實度</strong>：檢查 Agent 生成的最終代碼，是否確實呼叫了指定的驗證腳本（如 `scripts/check-endpoints.sh`）。'], 'metaphor': '就像在火災報警系統安裝完成後，安全員手持煙霧噴罐對著每個探測器進行噴煙測試，確保探測器既能在起火時第一秒刺耳報警，又不會因為有人噴香水而頻繁誤報。', 'layout': '測試驗證矩陣：展示正面觸發測試（綠色勾選）與負面排除測試（灰色排除）的自動化驗收結果。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 10, 'title': '合規與審計：Skill 調用記錄在 Session Trace 中的留痕', 'subtitle': '證明你在寫代碼時確實遵守了政策的法定證據', 'takeaway': 'Agent 在對話中加載了哪些 Skills，全數被如實記錄在 Session 日誌中，成為日後安全審計的無可辯駁之證。', 'details': ['<strong>追溯代碼合規起因</strong>：當審計員詢問『為什麼這個介面強制使用了特定的 JWT 結構？』工程師能直接調出該 Session 載入該 Skill 的歷史留痕。', '<strong>量化制度遵從率</strong>：企業安全主管可透過審查 Session Trace 大數據，統計全公司 API 任務中安全 Skill 的加載率是否達到 100%。', '<strong>持續改進依據</strong>：如果發現某些項目雖然觸發了 Skill 但依然需要人工修正，代表 Skill 描述不夠具體，指導安全團隊持續打磨文檔。'], 'metaphor': '這就像民航客機的『飛行資料記錄器（黑盒子）』：飛機起飛過程中有沒有依照標準作業程序開啟襟翼、有沒有放下起落架，感測器每一秒都有數位訊號留存備查。', 'layout': '審計日誌 JSON 截圖：展示 Session Trace 中記錄的 Skill 觸發時間戳、版本號與對應代碼生成歷史。'}, {'chapter_id': 8, 'chapter_name': '第 8 章：Stage 3: Build — 制度化知識：Skills 深度應用', 'page_num': 11, 'title': '第八章實戰總結：讓資深專家的智慧全天候賦能', 'subtitle': 'Stage 3 Build 制度化沉澱核心總結與下章預告', 'takeaway': 'Skills 讓個人智慧昇華為組織集體智慧，但要築起絕對不可攻破的鋼鐵長城，我們必須在下一章請出真正的硬門禁——Hooks！', 'details': ['<strong>核心心法</strong>：將不言自明的潛規則挑出來、封裝為標準 SKILL.md、設定精確 YAML 觸發詞、用 Plugin 全局分發。', '<strong>銘記本質</strong>：Skill 是柔性智力引導，它讓違規變稀少；但要讓違規徹底不可能，必須依賴下一章的確定性防衛！', '<strong>前瞻第九章</strong>：如何寫一個毫秒級的本地腳本，在 Agent 意圖碰觸受保護目錄時瞬間將其阻斷？第九章 Hooks 將為您揭密！'], 'metaphor': '每一位資深架構師都無法分身坐在每一位工程師旁邊指導，但透過 Skills，他的智慧與原則宛如分身億萬，安靜地守護在每一次人機協同的鍵盤敲擊旁。', 'layout': '三條核心實踐卡片，底部搭配通往第九章 Hooks 的鋼鐵防禦箭頭。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 1, 'title': '確定性防線的不可替代性：為什麼需要 Hooks？', 'subtitle': '當柔性提示詞面臨嚴苛合規時，必須有一道實體物理防線', 'takeaway': 'Hooks 是底層的確定性腳本層，在 Agent 執行文件修改或終端命令的微秒瞬間進行強制攔截。', 'details': ['<strong>Prompt 不是防彈衣</strong>：提示詞存在微小機率被繞過或忽視，在受監管行業中，『99% 遵守』等同於『0% 合規』。', '<strong>建置階段是最高頻戰場</strong>：在實作期間，Agent 絕大部分動作都是調用 File Edit 與 Shell Bash，這正是 Hooks 大顯身手的最佳卡點。', '<strong>毫秒級本地攔截</strong>：不依賴昂貴的雲端 API 往返，純本地 Shell/Python 腳本瞬間完成正則與路徑檢驗，零延遲守護環境。'], 'metaphor': '如果說 Skill 是航海圖上的暗礁標註，那麼 Hook 就是船頭配備的高靈敏度聲納自動防撞制動器，一旦探測到距離礁石只有十米，自動切斷主機動力，絕不由人機爭辯。', 'layout': '雙層防禦架構圖：外層為 Skill 智慧導引，內層為厚實的 Hook 鋼鐵閘門，精準卡位在 Agent 與作業系統核心之間。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 2, 'title': '三大典型守護場景：保護路徑、格式化與憑證防洩', 'subtitle': 'Anthropic 官方推薦的建置期三大必備 Hook 策略', 'takeaway': 'Build-time Hooks 的核心任務：阻斷受保護路徑修改、自動執行 Formatter 防止漂移、杜絕金鑰憑證外洩。', 'details': ['<strong>場景一：阻斷保護路徑編輯</strong>：禁止 Agent 篡改自動生成的程式碼類（如 `src/gen/`）、資料庫遷移歷史或已凍結的舊版本包（`v1/`）。', '<strong>場景二：即時自動格式化與 Lint</strong>：在檔案編輯後自動調用 prettier/eslint，將代碼風格差異消滅在萌芽狀態，保持 Git 歷史乾淨。', '<strong>場景三：憑證與金鑰硬攔截</strong>：即時掃描即將寫入的文本，一旦發現匹配 AWS Key、JWT Token 或私鑰正則，立刻暴力中斷！'], 'metaphor': '這就像在精密晶圓廠車間門口安裝的三道感應閘門：第一道攔截未授權人員進入核心光刻區（保護路徑），第二道強制吹風除塵（格式化），第三道金屬探測器攔截未報備電子設備（憑證防洩）。', 'layout': '三防衛盾牌卡片：分別展示 Protected Paths、Auto-formatters、Secret Detection 的實體過濾邏輯。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 3, 'title': '輕量快速原則 (Fast and Scoped)：避免拖垮心流', 'subtitle': '為什麼全量單元測試絕對不能放在 Build Hook 裡？', 'takeaway': 'Build 階段的 Hook 必須極速運行（<100ms），且嚴格限制在當前修改的單一檔案範圍內。', 'details': ['<strong>微秒級響應要求</strong>：Agent 在寫代碼時可能一分鐘內進行十幾次微調，如果每次保存都要等待 2 分鐘跑完整個測試套件，心流將被徹底摧毀。', '<strong>分層把關哲學</strong>：輕量檢查（路徑白名單、語法 Lint、格式化）放在每次動作的 Hook；重量級全量測試與安全掃描留到 Commit 或 PR 階段。', '<strong>單檔案聚焦 (Scoped)</strong>：只針對 `$TOOL_INPUT` 中正在改動的單一檔案進行檢驗，絕不引發跨模組的連鎖編譯負擔。'], 'metaphor': '如同高速公路上的收費閘口：ETC 電子感應器必須在 0.1 秒內完成扣款抬桿（輕量 Hook），你絕不能在收費口強迫司機把整輛車拆開進行全面的年度汽車大修檢驗（全量測試）。', 'layout': '時間軸對比圖：展示 <50ms 的輕量級 Hook 順暢流動，與耗時 >30s 的臃腫 Hook 導致終端徹底凍結的災難對比。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 4, 'title': 'PreToolUse 攔截機制：在動作生效前奪回控制權', 'subtitle': 'Anthropic 架構深度揭秘：Tool 調用前的最後審判', 'takeaway': 'PreToolUse Hook 賦予系統在 Agent 的意圖轉化為真實系統調用之前，進行檢查與裁決的絕對權力。', 'details': ['<strong>標準 JSON 輸入通道</strong>：Claude 在決定調用工具時，底層將工具名稱與入參打包為標準 JSON，透過 stdin 管道輸入給 Hook 腳本。', '<strong>透明深入的參數檢查</strong>：腳本利用 `jq` 輕鬆解析 Agent 意圖編輯的檔案名、寫入的內容片段或打算執行的終端 Shell 命令。', '<strong>三大裁決走向</strong>：允許執行 (Allow, exit 0)、攔截阻斷 (Block, exit 2)，或在發布階段轉交人類審批 (Ask)。'], 'metaphor': '就像最高法院法官在行政命令正式加蓋國璽、頒布生效的前一秒，擁有憲法賦予的緊急禁制令簽發權，一票否決任何違憲指令。', 'layout': '資料管道時序圖：Agent Tool Use Intent → stdin 注入 Hook 腳本 → jq 解析入參 → 輸出 Exit Code 裁決結果。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 5, 'title': '阻斷與自省：退出碼 2 (Exit 2) 與友善引導', 'subtitle': '好的 Hook 不僅要能殺人，更要能教人：引導 Agent 自我修正', 'takeaway': '當 Hook 決定阻斷時，必須退出碼為 2，並將清晰的阻斷原因與合規路徑寫入 stderr，讓 Agent 能立刻調整策略。', 'details': ['<strong>標準退出碼語意</strong>：Exit 0 表示完全合規、批准執行；Exit 2 表示確定性阻斷，且 stderr 中的文字將直接作為環境反饋回傳給 Claude。', '<strong>提供清晰的導航指南</strong>：不要只冷冰冰地印出『Permission Denied』，而應輸出：『禁止修改 v1/legacy 目錄；所有新功能必須實現在 v2/ 目錄下』。', '<strong>激發 Agent 的自我調整</strong>：Claude 讀到這條錯誤提示後，會立即向工程師致歉，並在 plan.md 中調整路徑，重新在合規目錄下建立檔案！'], 'metaphor': '就像迷宮裡的智慧防撞牆：當老鼠撞上牆壁時，牆壁不是放電把它電死，而是亮起一個語音箭頭指示：『此路不通，請向右轉進入第二號通道』。', 'layout': '雙向終端反饋圖：展示 Hook 輸出 Exit 2 包含詳細提示，Claude 收到提示後自動改變實作路徑的智能適應過程。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 6, 'title': '保護測試防篡改：捍衛驗證真偽性的防護罩', 'subtitle': '杜絕 Agent 投機取巧：任何修復任務禁止改動現有測試', 'takeaway': '在 Bug 修復任務中，必須透過 Hook 物理封死對測試目錄的寫入權限，確保紅燈變綠燈是真正修復了業務代碼。', 'details': ['<strong>Agent 的偷懶本能 (Short-circuiting)</strong>：有時為了讓測試通過，模型可能會投機取巧地把斷言改小（例如將 `assert result == 100` 改為 `assert result >= 0`）。', '<strong>測試檔案防竄改 Hook</strong>：當當前任務為 Bug Fix 時，Hook 匹配 `test/**` 或 `*_test.go` 檔案路徑，一旦有寫入意圖直接 exit 2 阻斷。', '<strong>確保綠燈含金量 100%</strong>：被保護的測試套件是系統唯一的尺規；唯有尺規不可動搖，測量出來的品質才是真金白銀。'], 'metaphor': '這就像在高考考場上，考生絕不可能被允許拿著紅筆去修改試卷評分標準答案；你只能竭盡全力把題目算對，絕不能把答案卷的標準改成你算錯的數字。', 'layout': '天平圖示：左側為受保護的不可篡改測試檔案（標註防護罩），右側為被嚴格檢驗的業務代碼。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 7, 'title': '為什麼不能在 Build 階段放入真人審批彈窗？', 'subtitle': '避免人肉塞車：把需要人批准的關卡留給 Stage 5 Deploy', 'takeaway': '建置期的 Hook 必須是『全自動允許或阻斷』，絕不能彈窗等待真人確認，否則將徹底摧毀並行多線作業。', 'details': ['<strong>並行架構的致命毒藥</strong>：當一位工程師在背景掛著三個 Worktrees 同時跑任務時，任何一個終端彈出人肉確認，都會直接凍結該任務的心流。', '<strong>非黑即白的建置邏輯</strong>：建置期間要麼合規放行、要麼違規阻斷；凡是需要人類判斷『是否放行發布』的權力，統一收攏至 Stage 5 的 Release Gate。', '<strong>維持極致吞吐量</strong>：讓 Agent 在安全沙盒內全速前進，人的注意力只在起點（Plan）和終點（PR Review/Deploy）進行高品質裁決。'], 'metaphor': '就像在半導體無人全自動無塵室晶圓傳送流水線上，你絕不能在兩台精密光刻機之間安排一個人工收費亭，每送一片晶圓就得人工蓋一次章，整個千億產線將瞬間癱瘓。', 'layout': '架構警示對比圖：展示 Build 階段插入人工審批導致的所有線程卡死紅燈，與統一收口至 Deploy 階段的順暢綠燈。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 8, 'title': '設定檔配置範例：.claude/settings.json 語法拆解', 'subtitle': '如何用幾行簡潔的 JSON 聲明一個全局匹配的 PreToolUse Hook？', 'takeaway': '標準配置直觀優雅，支援按工具類型（Bash、FileEdit）進行正則匹配並掛載執行腳本。', 'details': ['```json\n{\n  "hooks": {\n    "PreToolUse": [\n      {\n        "matcher": "Bash",\n        "hooks": [\n          {\n            "type": "command",\n            "command": "${CLAUDE_PROJECT_DIR}/.claude/hooks/protect-secrets.sh"\n          }\n        ]\n      }\n    ]\n  }\n}\n```', '<strong>變數精準尋址</strong>：`${CLAUDE_PROJECT_DIR}` 自動解析當前工程根目錄，保證跨平台與團隊成員路徑一致性。', '<strong>多工具疊加防護</strong>：可同時為 `Bash`、`FileEdit`、`FileWrite` 等多個核心工具掛載專屬的校驗鏈條。'], 'metaphor': '宛如現代智能家居的自動化觸發器設定：『當感測器偵測到窗戶被打開時（Matcher），立刻執行拉響警報器腳本（Command）』，簡明扼要且嚴密可靠。', 'layout': 'JSON 語法高亮卡片，各欄位旁附帶浮動標籤解釋其作用與匹配邏輯。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 9, 'title': '保護機密實戰腳本：protect-secrets.sh 實作剖析', 'subtitle': '短短十行 Shell，如何在終端底層築起防洩密天羅地網？', 'takeaway': '透過讀取 stdin 中的命令文本，用 grep 正則瞬間甄別潛在私鑰與機密外洩風險。', 'details': ['```bash\n#!/bin/bash\n# 讀取 Claude 即將執行的命令文本\ncmd=$(jq -r \'.tool_input.command // empty\' < /dev/stdin)\nif [ -z "$cmd" ]; then exit 0; fi\n\n# 檢驗是否包含關鍵機密檔或特權指令\nif echo "$cmd" | grep -E -q \'(id_rsa|\\.env|AWS_SECRET|credentials)\'; then\n  echo "[Security Hook] 嚴重阻斷：檢測到指令觸及敏感憑證路徑！" >&2\n  echo "請改用環境變數注入或聯絡安全團隊授權。" >&2\n  exit 2\nfi\nexit 0\n```', '<strong>攔截即銷毀</strong>：命令在尚未送達作業系統內核前就被徹底掐死，日誌中絕不留下任何洩密痕跡。'], 'metaphor': '這就是防毒軟體中的『實時啟發式文件防火牆』，在病毒即將被雙擊運行的千分之一秒前，內核驅動瞬間將其隔離封裝。', 'layout': '代碼區塊完整展示 protect-secrets.sh，並標註 stdin 讀取、正則判定與 Exit 2 阻斷三大環節。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 10, 'title': '受管設定 (Managed Settings) 的不可覆蓋性', 'subtitle': '防止個別員工擅自關閉防禦：全組織維度的強制策略繼承', 'takeaway': '企業非妥協性 (Non-negotiable) 的底線 Hooks 存放於受管系統目錄，個別工程師在本地配置中無法停用或覆蓋。', 'details': ['<strong>個人設定與組織設定的層次劃分</strong>：工程師可在 `.claude/settings.json` 中添加輔助個人習慣的友善 Hook。', '<strong>管理員策略強制覆蓋</strong>：由 IT/Platform 部署於系統級目錄（如 `/etc/claude/` 或 Windows 註冊表策略）的受管配置擁有最高優先權。', '<strong>合規合法的基石</strong>：即使工程師本地誤刪了 `.claude/` 目錄，核心安全攔截網依然在全局生效，徹底滿足 SOC2/ISO27001 審計標準。'], 'metaphor': '如同公司發配的商務筆記本電腦：員工可以自由更換桌面壁紙和滑鼠游標（個人設定），但硬碟全盤加密 BitLocker 與企業防毒軟體，員工哪怕擁有管理員權限也絕對無法解除卸載（受管設定）。', 'layout': '雙層配置覆蓋圖：上層個人配置遇到下層組織受管配置時，衝突條款強制以受管策略為準。'}, {'chapter_id': 9, 'chapter_name': '第 9 章：Stage 3: Build — 確定性防禦：Build-time Hooks', 'page_num': 11, 'title': '第九章實戰總結：將安全性深植於每一次工具調用', 'subtitle': 'Stage 3 Build 確定性防禦核心總結與下章預告', 'takeaway': 'Hooks 與 Skills 構成了軟硬一體的絕妙防禦組合拳，讓團隊既能放手奔馳，又永遠高枕無憂！', 'details': ['<strong>核心公式</strong>：輕量化腳本 + 嚴格範圍限定 + PreToolUse 毫秒截殺 + Exit 2 智能自省引導。', '<strong>安全基線已立</strong>：至此，我們已經為建置期打造了完整的智慧大腦（CLAUDE.md）、專業外掛（Skills）與防禦裝甲（Hooks）。', '<strong>前瞻第十章</strong>：單兵作戰已經無懈可擊，如何進一步組織大規模 Agent 兵團並行推進？第十章『Parallel Sessions & Subagents』將帶您進入集群協同的新紀元！'], 'metaphor': '當鋼鐵裝甲已經武裝到牙齒，每一發子彈都有智慧制導與自爆保險，現在正是吹響衝鋒號角、調集千軍萬馬協同作戰的黃金時刻！', 'layout': '三條核心實踐卡片，底部搭配通往第十章並行協同的高亮躍遷箭頭。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 1, 'title': '一人驅動多條戰線：並行會話 (Parallel Sessions) 的魅力', 'subtitle': '打破單線程瓶頸：一名工程師如何同時推進多個複雜專案？', 'takeaway': '並行會話是指在各自獨立的 Git Worktree 中啟動多個完整的 Claude Code 實例，各任務互不干擾、同時並進。', 'details': ['<strong>單線程等待的巨大浪費</strong>：傳統模式下，工程師開著一個終端等待 Agent 思考或運行測試，這段時間人的智力被迫閒置。', '<strong>任務間的物理隔離</strong>：不同任務在檔案系統層面完全分離，各自擁有獨立的分支與工作目錄，消除衝突。', '<strong>工程師的總體指揮權</strong>：各並行會話彼此完全不知曉對方的存在，唯一的紐帶就是身處中央調度室、掌握全局的工程師本人。'], 'metaphor': '就像一家大型建築工程公司的總指揮，同時指揮著 A 區的體育館鋼結構吊裝、B 區的五星級酒店內部裝潢與 C 區的地下管網鋪設，各工區互不干擾，總進度神速推進。', 'layout': '星狀拓撲圖：中央為人類工程師指揮官，向外輻射連接三個並行的 Claude Code 終端進程。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 2, 'title': '什麼是 Subagent？會話內部的專職特戰隊', 'subtitle': '獨立上下文與工具白名單：解決特定重複性專業任務的利器', 'takeaway': 'Subagent 是在單一會話內部運行的輕量特化助手，擁有獨立的上下文窗口與工具限制，避免污染主會話記憶體。', 'details': ['<strong>上下文保護 (Context Protection)</strong>：如果讓主 Agent 去做耗費幾萬 Token 的全文搜索或代碼簡化，主會話的注意力將迅速被無關日誌沖垮。', '<strong>工具最小權限原則 (Least Privilege)</strong>：例如只給予 Researcher 讀取權限（Read/Grep），剝奪其寫入權限，確保安全探索。', '<strong>專業化聚焦 (Specialization)</strong>：專人專事，例如 Verifier 專職負責環境啟動與行為驗收，Simplifier 專職精簡重構冗餘邏輯。'], 'metaphor': '如同主治外科醫生在手術台上，身邊隨時跟隨專職的麻醉師、器械護士與巡迴護士（Subagents）；主刀醫生不需要親自去清洗消毒鑷子，只需發出指令，助手精準完成後報告結果。', 'layout': '雙層架構對照圖：展示主會話（Main Agent）如何派遣並管理多個具備獨立 Context 視窗的專職 Subagents。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 3, 'title': 'Parallel Sessions vs Subagents：本質維度對比', 'subtitle': 'Anthropic 官方核心架構：水平擴展 vs 垂直深耕', 'takeaway': 'Parallel Sessions 提升了一名工程師同時處理的『任務數量』；Subagents 則確保了單個任務內部的『極致專注與上下文純淨』。', 'details': ['<strong>Parallel Sessions（並行會話）</strong>：橫向擴充。完全獨立的進程、獨立的 Git Worktree、處理完全不同的業務功能，由人協調。', '<strong>Subagents（子代理人）</strong>：縱向專業化。附屬於某個主會話、共享工作目錄、處理任務內部的特定子階段，由主 Agent 調度。', '<strong>二者合力的化學反應</strong>：工程師開啟三個並行會話，每個會話內部又按需調用 Subagents，構成強大的蜂巢式研發軍團！'], 'metaphor': 'Parallel Sessions 就像是同時派出三艘獨立的深海科考船前往太平洋、大西洋與印度洋（多任務並行）；而每艘船上又配備了專職的潛水員、聲納員與標本採集員（Subagents）。', 'layout': '2x2 矩陣圖：從進程隔離度、上下文邊界、調度發起者與核心目的四個維度全面對照二者。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 4, 'title': '任務拆解的藝術：依檔案相依性劃分無衝突邊界', 'subtitle': '並行作業的先決條件：利用 plan.md 識別解耦模組', 'takeaway': '凡是觸及相同檔案的任務，必須在單一會話中循序執行；凡是操作不同模組且檔案無交集的任務，大膽並行開工！', 'details': ['<strong>依據 plan.md 判定邊界</strong>：回顧 Stage 3 初期的 plan.md，精確比對各任務的 `Files that change` 清單。', '<strong>零衝突保證</strong>：任務 A 修改 `portal/src/claims/`，任務 B 修改 `api/payment/`，兩者毫無交集，是完美的並行候選者。', '<strong>及早發現潛在死鎖</strong>：如果兩個任務都需要重構同一個共用工具函式庫 `utils/auth.ts`，強制排期為先後依序推進，避免 Git Merge 地獄。'], 'metaphor': '這就像交響樂團排練：管樂部在主音樂廳練習，弦樂部在隔音排練室練習（無衝突並行）；但如果要合奏同一首協奏曲的高潮段落（共用代碼），大家必須在同一個大廳聽從同一個拍子。', 'layout': '依賴分析文氏圖：展示兩個無交集的集合（並行）與一個有重疊交集的集合（序列推進）。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 5, 'title': 'Git Worktrees 實戰指南：零成本創建隔離工作區', 'subtitle': '徹底淘汰傳統笨拙的 git checkout 分支切換手法', 'takeaway': '一行指令建立全新目錄與分支，讓多個終端同時對不同代碼空間進行讀寫，互不踩腳。', 'details': ['```bash\n# 終端 1：開闢認證功能獨立工作區\nclaude --worktree feature-auth\n\n# 終端 2：開闢修復限流問題獨立工作區\nclaude --worktree fix-rate-limit\n```', '<strong>共享底層對象庫，極致節省空間</strong>：Git Worktree 不需要像完整 git clone 那樣重複複製全部歷史記錄，瞬間完成目錄掛載。', '<strong>徹底杜絕編譯暫存污染</strong>：前端的 `node_modules` 與構建產物在各自目錄內獨立生成，再也不會發生分支切換導致熱更新崩潰。'], 'metaphor': '這就像在同一個中心圖書館旁，為兩位研究員各自搭建了一間獨立的隔音研究室，兩間房間共用圖書館的藏書底庫，但各自桌面上攤開的筆記稿紙互不影響。', 'layout': '代碼終端視窗對比：展示終端 1 與終端 2 在不同工作目錄下的命令調用與乾淨隔離狀態。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 6, 'title': '控制並行會話的極限：人類專注力才是真正上限', 'subtitle': '不要貪多嚼不爛：兩到三個會話是黃金平衡點', 'takeaway': '技術上你可以同時啟動二十個 Claude Code，但實務上的天花板取決於你能高品質審查多少條產出流。', 'details': ['<strong>審查超載與防禦崩潰</strong>：如果同時開啟 10 個任務，工程師將再次陷入認知癱瘓，無法仔細驗收任何一個產物，本末倒置。', '<strong>2~3 個會話的黃金律動</strong>：當 Session 1 在跑編譯與測試時，審查 Session 2 的計畫，並在 Session 3 與產品經理確認邊界，節奏行雲流水。', '<strong>只有當審查跟得上時才加任務</strong>：守住審查品質底線，絕不盲目追求終端機窗口的數量虛榮。'], 'metaphor': '如同特技雜耍雜技演員同時在空中拋接彩球：經驗豐富的演員接拋三個球可以維持一小時不落地且姿態優雅；但如果硬塞給他十個球，幾秒鐘後所有球都會劈啪掉在地上砸碎。', 'layout': '專注力曲線圖：展示並行會話從 1 個提升至 3 個時產能直線飆升，超過 4 個後因審查疲勞導致品質急墜。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 7, 'title': 'Subagent 定義規範：以 .claude/agents/ 為家', 'subtitle': '用聲明式 Markdown 定義專屬子特工的角色與工具白名單', 'takeaway': '每個 Subagent 都是存放在 `.claude/agents/<name>.md` 的獨立文件，由全團隊透過 Git 共同分享與維護。', 'details': ['<strong>標準存放目錄</strong>：倉庫根目錄的 `.claude/agents/`，團隊成員隨時可共享已驗證的特工設定。', '<strong>YAML 前置參數</strong>：定義特工名稱 (name)、適用時機描述 (description) 與允許調用的工具清單 (tools)。', '<strong>正文角色提示詞 (System Prompt)</strong>：給出清晰的行為準則、禁止動作與輸出格式規範。'], 'metaphor': '這就像特警部隊的『特種戰術崗位說明書』：明確定義狙擊手（狙擊槍、夜視鏡、禁止近戰衝鋒）與防暴手（防彈盾牌、催淚彈、禁止擅自開火）的裝備與作戰手則。', 'layout': '檔案結構剖析圖：展示 `.claude/agents/` 目錄下的多個 `.md` 特工定義卡片。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 8, 'title': '官方實戰特工拆解：verifier.md 驗證員', 'subtitle': 'Anthropic 原生定義：獨立於編碼上下文的客觀質檢官', 'takeaway': 'Verifier 擁有完全乾淨的上下文窗口，不受主 Agent 編碼時的主觀偏見影響，客觀啟動應用並檢驗行為。', 'details': ['```markdown\n---\nname: verifier\ndescription: Runs the app and checks the change works before the session\n  reports done\ntools: Bash, Read\n---\nStart the app with make run. Exercise the changed behavior and the two\nnearest neighboring flows. Report what you ran, what you saw, and any\nbehavior that does not match plan.md. Do not fix anything; report only.\n```', '<strong>乾淨視野 (Fresh Context)</strong>：沒有任何編碼時的思維定勢與藉口，純粹以黑盒角度運行程式並對照 plan.md 驗收。', '<strong>職責隔離：只報告、不修復</strong>：『Do not fix anything; report only』防止質檢員自作主張越權修補，維持客觀中立。'], 'metaphor': '就像汽車製造廠裡專門的『出廠質檢員』：他沒有參與發動機的打磨與組裝，他拿著質檢單坐進駕駛座發動引擎、猛踩煞車、測試空調，任何不符合指標的瑕疵直接貼上紅標駁回。', 'layout': '代碼高亮完整呈現 verifier.md 全文，重點註解『tools 白名單』與『只報告不修復』核心條款。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 9, 'title': '經典特工軍團：Simplifier 與 Researcher', 'subtitle': '專職化特工生態：為特定高頻工作流打造專屬助手', 'takeaway': '除了 Verifier，團隊中最受歡迎的兩大專職特工分別為：代碼瘦身專家 (Simplifier) 與情報偵察兵 (Researcher)。', 'details': ['<strong>Code Simplifier（代碼精簡員）</strong>：在主 Agent 完成功能後介入，專職掃除冗餘代碼、內聯無謂的單次抽象、去除過度設計，讓 Diff 極致優雅。', '<strong>Codebase Researcher（代碼庫偵察員）</strong>：配備 Read/Grep 工具，深入未知大型代碼庫搜集函式調用鏈與型別定義，輸出簡要報告而絕不污染主會話。', '<strong>特工組合拳</strong>：主 Agent 規劃編碼 → Simplifier 瘦身整理 → Verifier 啟動驗證，流水線一氣呵成。'], 'metaphor': '就像電影劇組裡的各司其職：導演（主 Agent）負責說戲指導拍攝，燈光攝影（Researcher）負責布光取景，剪輯師（Simplifier）負責咔嚓剪掉贅餘鏡頭，質檢放映員（Verifier）負責檢查拷貝色彩音軌。', 'layout': '特工協同工作流卡片：展示 Researcher → Main Agent → Simplifier → Verifier 依序銜接的精確節奏。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 10, 'title': '並行治理與合規：更多會話意味著更嚴格的倉庫配置', 'subtitle': '多線推進下的權限歸屬與審計歸因', 'takeaway': '會話數量增加導致代碼產出暴增，所有會話必須強制繼承倉庫根目錄的 Hooks 與 Managed Settings，所有行為歸因至啟動工程師。', 'details': ['<strong>防禦配置的全局穿透</strong>：無論開啟多少個並行會話或派遣多少個子代理，根目錄的 PreToolUse Hooks 毫無例外地對所有終端生效。', '<strong>不可抵賴的身分歸因</strong>：每個會話產生的 Git Commit 與操作日誌，全數綁定啟動該終端的工程師帳號，確保權責清晰。', '<strong>資源與費用熔斷</strong>：企業可集中設定每位工程師的同時在線會話上限與 API 費用配額，防止背景無效空轉消耗資金。'], 'metaphor': '這就像軍隊指揮系統：無論派遣多少個獨立特戰小隊深入敵後作戰，每位隊員的無線電通訊都受到中央指揮部的加密監聽，每顆發射的子彈都登記在該分隊指揮官名下。', 'layout': '中央控制台視圖：展示企業管理員統一監控多個並行會話的活躍狀態、資源佔用與安全合規日誌。'}, {'chapter_id': 10, 'chapter_name': '第 10 章：Stage 3: Build — 多代理人協作：Subagents 專職分工', 'page_num': 11, 'title': '第十章實戰總結：邁向集群協同的工程大格局', 'subtitle': 'Stage 3 Build 建置全階段圓滿收官與下章預告', 'takeaway': '我們完成了從 Plan Mode、Auto Mode、CLAUDE.md、Skills、Hooks 到集群並行的全面佈局，正式敲開 Stage 4 Test 的大門！', 'details': ['<strong>建置階段核心全景</strong>：思考先於編碼 (Plan) → 安全自主加速 (Auto) → 開機大腦智慧 (CLAUDE.md) → 機構規範 (Skills) → 確定性防禦 (Hooks) → 集群並行 (Subagents)。', '<strong>代碼已經寫好，如何證明它正確？</strong>：沒有經過嚴密自檢的代碼不能交付，第十一章我們將解鎖 Stage 4 的『Feedback Loops 驗證反饋循環』！'], 'metaphor': '我們已經建立了一支紀律嚴明、武裝到牙齒且配備高科技協同通訊的現代化工程兵團；現在，我們將把這支部隊開赴最殘酷的實戰檢驗場——自動化驗證與評測！', 'layout': 'Stage 3 全六大核心機制徽章總覽，正中央指向 Stage 4 Test 的明亮大門。'}]
